<script setup lang="ts">
/**
 * Demo: SnVideoPreview — basic media box with a poster and inline playback.
 *
 * `controls` (default `true`) renders OUR custom bar, never the browser's
 * native one — see the "custom bar vs native" demo for the difference.
 */
import { SnVideoPreview } from '@snui/vue-web';

/**
 * 自包含视频源（data URI）。取自 Web Platform Tests 的 media/2x2-green.mp4
 * （BSD-3-Clause），demo 不依赖任何外网视频源。
 */
const videoSrc =
  'data:video/mp4;base64,';

/** 自包含封面（SVG data URI），demo 不依赖外网图片源。 */
function poster(from: string, to: string, label = '', w = 640, h = 360): string {
  const parts = [
    `<svg xmlns="http://www.w3.org/2000/svg" width="${w}" height="${h}">`,
    `<defs><linearGradient id="g" x1="0" y1="0" x2="1" y2="1"><stop offset="0" stop-color="${from}"/><stop offset="1" stop-color="${to}"/></linearGradient></defs>`,
    `<rect width="${w}" height="${h}" fill="url(#g)"/>`,
    `<circle cx="${w * 0.78}" cy="${h * 0.26}" r="${h * 0.26}" fill="rgba(255,255,255,0.16)"/>`,
  ];
  if (label) {
    parts.push(
      `<text x="50%" y="52%" fill="rgba(255,255,255,0.92)" font-family="system-ui,sans-serif" font-size="${Math.round(h * 0.1)}" font-weight="600" text-anchor="middle" dominant-baseline="middle">${label}</text>`,
    );
  }
  parts.push('</svg>');
  return `data:image/svg+xml;charset=utf-8,${encodeURIComponent(parts.join(''))}`;
}
</script>

<template>
  <div class="demo-row">
    <SnVideoPreview
      :src="videoSrc"
      :poster="poster('#69b1ff', '#0958d9', 'Promo film')"
      title="Promo film"
    />
    <SnVideoPreview
      :src="videoSrc"
      :poster="poster('#5cdbd3', '#08979c', 'Photo walk')"
      title="Photo walk"
      alt="Photo walk clip"
      :width="240"
      aspect-ratio="16 / 9"
    />
  </div>
</template>

<style scoped>
.demo-row {
  display: flex;
  gap: 16px;
  align-items: flex-start;
}
</style>
